{
  "title": "Weekend Trip To-Do",
  "body": "<div class="wrap"><h2>Weekend trip planning</h2><div class="add"><input id="draft" type="text" placeholder="Add a task…" value=""></input><button id="add">Add</button></div><ul id="list"></ul><p id="count"></p></div>",
  "css": ".wrap{font-family:sans-serif;max-width:420px;margin:0 auto;padding:12px}h2{margin:0 0 12px;font-size:1.2em}.add{display:flex;gap:8px;margin-bottom:12px}.add input{flex:1;padding:8px;border:1px solid #bbb;border-radius:6px}.add button{padding:8px 14px;border:0;border-radius:6px;background:#2b6cb0;color:#fff;cursor:pointer}ul{list-style:none;margin:0;padding:0}li{display:flex;align-items:center;gap:10px;padding:8px 6px;border-bottom:1px solid #eee}li span{flex:1}li.done span{text-decoration:line-through;color:#888}.tick{width:24px;height:24px;border:2px solid #2b6cb0;border-radius:6px;background:#fff;color:#2b6cb0;cursor:pointer;line-height:1;padding:0}li.done .tick{background:#2b6cb0;color:#fff}.del{border:0;background:transparent;color:#c53030;cursor:pointer;font-size:1em}#count{color:#555;font-size:.9em;margin-top:12px}",
  "scripts": [
    "if (!state.items) { state.items = [{id:1,text:'Pick a destination and book accommodation',done:false},{id:2,text:'Plan transport and check the weather forecast',done:false},{id:3,text:'Make a packing list',done:false}]; state.nextId = 4; state.draft = ''; }
const render = () => {
  const list = root.byId.list;
  list.children = state.items.map(it => ({
    tag: 'li', attrs: { class: it.done ? 'done' : '' }, text: '',
    children: [
      { tag: 'button', attrs: { class: 'tick' }, text: it.done ? '✓' : '', children: [], on: { click: () => { it.done = !it.done; render(); } } },
      { tag: 'span', attrs: {}, text: it.text, children: [] },
      { tag: 'button', attrs: { class: 'del' }, text: '✕', children: [], on: { click: () => { state.items = state.items.filter(x => x.id !== it.id); render(); } } }
    ]
  }));
  const left = state.items.filter(x => !x.done).length;
  root.byId.count.text = state.items.length === 0 ? 'Nothing here yet — add a task!' : (left === 0 ? 'All done! 🎉' : `${left} left of ${state.items.length}`);
};
root.byId.draft.attrs.value = state.draft;
root.byId.draft.on = { input: (e) => { state.draft = e.value; } };
root.byId.add.on = { click: () => {
  const t = (state.draft ?? '').trim();
  if (t) { state.items.push({ id: state.nextId, text: t, done: false }); state.nextId = state.nextId + 1; }
  state.draft = '';
  root.byId.draft.attrs.value = '';
  render();
} };
render();"
  ]
}
